#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /mycelium-extra:setup-wizard skill.
#
# Adapted from the wizard skill template by Matt Pocock, MIT License,
# Copyright (c) 2026 Matt Pocock. Changed for HPC analysis setup: cluster
# helpers (sbatch test job, checksum check, setup log) replace the GitHub
# secrets helpers.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# Settings (environment, all optional):
#   SETUP_LOG         setup log, no secrets      (default: logs/SETUP.md)
#   SECRETS_FILE      mode-600 file for secrets  (default: ~/.config/mycelium-extra/setup.env)
#   MX_SBATCH_OPTS    extra sbatch options, e.g. "--partition=short --account=lab"
#   MX_TEST_WALLTIME  walltime of the test job   (default: 00:05:00)
#   MX_POLL_SECS      seconds between job polls  (default: 5)
#   MX_WIZARD_YES=1   TEST ONLY: auto-confirm every gate, skip pauses and browser
#                     opening. Never set it in a real run: it removes the
#                     confirmation before every irreversible action.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: consistent UX and safety, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
SETUP_LOG="${SETUP_LOG:-logs/SETUP.md}"
SECRETS_FILE="${SECRETS_FILE:-$HOME/.config/mycelium-extra/setup.env}"
MX_TEST_WALLTIME="${MX_TEST_WALLTIME:-00:05:00}"
MX_POLL_SECS="${MX_POLL_SECS:-5}"
WRITTEN_SECRET=()  # secret NAMEs written to SECRETS_FILE this run
SECRET_VALUES=()   # values entered this run, kept in memory only, so the log can refuse them
LOGGED=0           # lines appended to SETUP_LOG this run
SKIPPED=()         # things we could not do

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You do the manual steps; this wizard says exactly what to do and\n' "$DIM"
  printf '  records what you did in %s (no secrets). Stop any time with\n' "$SETUP_LOG"
  printf '  Ctrl-C and re-run later: finished stages can be skipped.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is an action the human takes.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
ok()   { printf '  %s✓ %s%s\n' "$GREEN" "$1" "$RESET"; }
die()  { printf '  %s✗ %s%s\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
# On a headless cluster node it prints the URL for you to open elsewhere.
open_url() {
  local url="$1"
  printf '  %s↗ open%s %s\n' "$GREEN" "$RESET" "$url"
  [[ "${MX_WIZARD_YES:-}" == 1 ]] && return 0
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1 && [[ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]]; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || note "no browser here: open the address above on your own machine"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  [[ "${MX_WIZARD_YES:-}" == 1 ]] && return 0
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes. Use it before any
# action that cannot be undone.
confirm() {
  local reply=""
  if [[ "${MX_WIZARD_YES:-}" == 1 ]]; then
    printf '  %s? %s [auto-yes, test mode]%s\n' "$YELLOW" "$1" "$RESET"
    return 0
  fi
  printf '  %s? %s [y/N] %s' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# ask KEY "Prompt" reads a visible (non-secret) value into $KEY. A value already
# in $KEY (from the environment) is the default: Enter keeps it. Fails at EOF.
ask() {
  local key="$1" prompt="$2" input s=$'\001' e=$'\002' p rc=0
  [[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || die "bad variable name: $key"
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "${!key:-}" ]] && p+="$s$DIM$e[Enter keeps: ${!key}]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "${!key:-}" ]] && input="${!key}"
  printf -v "$key" '%s' "$input"
}

# ── Setup log ─────────────────────────────────────────────────────────────

# _log_header creates SETUP_LOG with a short header when it is missing.
_log_header() {
  [[ -f "$SETUP_LOG" ]] && return 0
  mkdir -p "$(dirname "$SETUP_LOG")"
  printf '# Setup log\n\nWritten by a setup wizard. One line per action. No secrets: names and paths only.\n\n' > "$SETUP_LOG"
}

# log_setup "text" appends "- <date> <user>@<host>: text" to SETUP_LOG. It
# refuses text that contains a secret of 6 or more characters entered in this run.
log_setup() {
  local text="$1" v
  for v in ${SECRET_VALUES[@]+"${SECRET_VALUES[@]}"}; do
    (( ${#v} >= 6 )) && [[ "$text" == *"$v"* ]] && die "refused to log a line that contains a secret value"
  done
  _log_header
  printf -- '- %s %s@%s: %s\n' "$(date '+%F %H:%M')" "${USER:-user}" "$(hostname -s 2>/dev/null || echo host)" "$text" >> "$SETUP_LOG"
  LOGGED=$((LOGGED + 1))
}

# was_done NAME is true when SETUP_LOG already has "DONE NAME". Stages use it to
# offer a skip on a re-run. mark_done NAME writes that line.
was_done() {
  local line
  [[ -f "$SETUP_LOG" ]] || return 1
  while IFS= read -r line; do
    [[ "$line" == *": DONE $1" ]] && return 0
  done < "$SETUP_LOG"
  return 1
}
mark_done() { log_setup "DONE $1"; }

# skip_if_done NAME returns success (stage should be skipped) when it was done
# before and the human agrees to skip it.
skip_if_done() {
  was_done "$1" || return 1
  note "the log says \"$1\" was done before"
  confirm "Skip this stage?"
}

# record_access "dataset" logs who approved access to controlled data and when.
# It enforces nothing: the consent and disclosure terms are the human's to follow.
record_access() {
  local dataset="$1" who="" when=""
  warn "Controlled-access data: the access terms are yours to follow. This only records the decision."
  who="${ACCESS_APPROVER:-}"; [[ -n "$who" ]] || ask who "Who approved access (name or committee)?" || return 1
  when="${ACCESS_DATE:-$(date +%F)}"
  [[ "${MX_WIZARD_YES:-}" == 1 ]] || ask when "Approval date (YYYY-MM-DD):" || return 1
  log_setup "ACCESS $dataset approved_by=$who approved_on=$when"
}

# ── Secrets ───────────────────────────────────────────────────────────────

# _secret_path_ok FILE: a secret file may sit outside any git repository, or
# inside one only when git already ignores it.
_secret_path_ok() {
  local f="$1" dir; dir=$(dirname "$f")
  mkdir -p "$dir" 2>/dev/null || true
  if git -C "$dir" rev-parse --show-toplevel >/dev/null 2>&1; then
    git -C "$dir" check-ignore -q -- "$f" 2>/dev/null
  fi
}

# _existing KEY: current value of KEY in SECRETS_FILE, if any (undoes write_secret's quoting).
_existing() {
  [[ -f "$SECRETS_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$SECRETS_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  else return 1; fi
  printf '%s' "$value"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden and never echoed.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  [[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || die "bad variable name: $key"
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
  SECRET_VALUES+=("$input")
}

# write_secret KEY VALUE upserts KEY='VALUE' into SECRETS_FILE at mode 600.
# Refuses a file inside a git repository that git does not ignore. Idempotent.
# Never prints the value; the log gets the name only.
write_secret() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || die "bad variable name: $key"
  _secret_path_ok "$SECRETS_FILE" || die "$SECRETS_FILE is inside a git repository and not ignored: choose a path outside it, or add it to .gitignore first"
  SECRET_VALUES+=("$value")
  [[ -e "$SECRETS_FILE" ]] || (umask 077 && : > "$SECRETS_FILE")
  chmod 600 "$SECRETS_FILE"
  tmp=$(umask 077 && mktemp)
  grep -vE "^${key}=" "$SECRETS_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$SECRETS_FILE"
  rm -f "$tmp"
  WRITTEN_SECRET+=("$key")
  printf '  %s✓ wrote%s %s → %s (mode 600)\n' "$GREEN" "$RESET" "$key" "$SECRETS_FILE"
  log_setup "secret $key stored in $SECRETS_FILE"
}

# ── Cluster helpers ───────────────────────────────────────────────────────

# _job_state ID prints the job's state: squeue while queued or running, sacct
# after it ends. Empty when neither knows the job.
_job_state() {
  local s
  s=$(squeue -h -j "$1" -o %T 2>/dev/null | head -n1 || true)
  [[ -z "$s" ]] && s=$(sacct -n -X -P -j "$1" -o State 2>/dev/null | head -n1 | cut -d' ' -f1 || true)
  printf '%s' "$s"
}

# sbatch_test LABEL TIMEOUT_SECS COMMAND... writes a short test job, shows it,
# submits it after a confirm, polls until it ends or TIMEOUT_SECS pass, then
# prints the tail of its log. Returns 0 only when the job COMPLETED. On a
# timeout it leaves the job running and prints the scancel command; it never
# cancels for you. Set MX_SBATCH_OPTS for partition, account and so on.
sbatch_test() {
  local label="$1" timeout="$2" dir="logs/setup-jobs" script jid state="" waited=0 out
  shift 2
  command -v sbatch >/dev/null 2>&1 || { SKIPPED+=("test job $label: sbatch not found on this host"); warn "sbatch not found: run this wizard on a login node"; return 1; }
  mkdir -p "$dir"
  script="$dir/$label.sbatch"
  {
    printf '#!/bin/bash\n#SBATCH --job-name=mx-%s\n#SBATCH --output=%s/%s-%%j.log\n#SBATCH --time=%s\n' "$label" "$dir" "$label" "$MX_TEST_WALLTIME"
    printf '%s\n' "$*"
  } > "$script"
  say "Test job script ($script):"
  sed 's/^/    /' "$script"
  confirm "Submit this job with sbatch ${MX_SBATCH_OPTS:-}?" || { SKIPPED+=("test job $label not submitted"); return 1; }
  # MX_SBATCH_OPTS is split on purpose: it holds several options.
  # shellcheck disable=SC2086
  jid=$(sbatch --parsable ${MX_SBATCH_OPTS:-} "$script") || { warn "sbatch refused the job: read its message above"; log_setup "test job $label: sbatch refused"; return 1; }
  jid="${jid%%;*}"
  say "Submitted job $jid. Polling every ${MX_POLL_SECS}s, up to ${timeout}s."
  while true; do
    state=$(_job_state "$jid")
    case "$state" in
      PENDING|RUNNING|CONFIGURING|COMPLETING|REQUEUED|SUSPENDED) ;;
      "") (( waited > 0 )) && { state="UNKNOWN"; break; } ;;
      *) break ;;  # COMPLETED, FAILED, PREEMPTED and every other end state
    esac
    (( waited >= timeout )) && break
    sleep "$MX_POLL_SECS"; waited=$((waited + MX_POLL_SECS))
  done
  out="$dir/$label-$jid.log"
  [[ -f "$out" ]] && { say "Last lines of $out:"; tail -n 15 "$out" | sed 's/^/    /'; }
  case "$state" in
    COMPLETED) ok "job $jid COMPLETED"; log_setup "test job $label (job $jid) COMPLETED"; return 0 ;;
    UNKNOWN|"") warn "job $jid: no state from squeue or sacct; read the log above"; log_setup "test job $label (job $jid) state unknown"; return 1 ;;
    PENDING|RUNNING|CONFIGURING|COMPLETING|REQUEUED|SUSPENDED)
      warn "still $state after ${timeout}s. It keeps running. To stop it: scancel $jid"
      log_setup "test job $label (job $jid) still $state after ${timeout}s"; return 1 ;;
    *) warn "job $jid ended $state"; log_setup "test job $label (job $jid) $state"; return 1 ;;
  esac
}

# verify_checksums MANIFEST [DIR] runs sha256sum -c on MANIFEST inside DIR
# (default: the manifest's folder). Stops the wizard on any mismatch or missing
# file. It never deletes or renames a file.
verify_checksums() {
  local manifest="$1" dir out abs
  [[ -f "$manifest" ]] || die "manifest not found: $manifest"
  dir="${2:-$(dirname "$manifest")}"
  abs="$(cd "$(dirname "$manifest")" && pwd)/$(basename "$manifest")"
  # --strict: a malformed manifest line fails instead of leaving a file unchecked
  if out=$(cd "$dir" && sha256sum --strict -c "$abs" 2>&1); then
    ok "checksums match ($(grep -c ': OK$' <<<"$out") files in $manifest)"
    log_setup "checksums OK: $manifest ($dir)"
  else
    printf '%s\n' "$out" | grep -v ': OK$' | sed 's/^/    /' || true
    log_setup "checksums FAILED: $manifest ($dir)"
    die "checksum mismatch: fix the download yourself and re-run. Nothing was deleted."
  fi
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( LOGGED )) && note "logged $LOGGED line(s) to $SETUP_LOG"
  (( ${#WRITTEN_SECRET[@]} )) && note "wrote ${#WRITTEN_SECRET[@]} secret(s) to $SECRETS_FILE: ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
  return 0
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=1

banner "Cluster setup (example)"

# ── Example stage: replace with your real steps ───────────────────────────
# Helpers you can use here:
#   open_url URL            say / step / note / warn
#   ask KEY "Prompt"        ask_secret KEY "Prompt"  then  write_secret KEY "$KEY"
#   sbatch_test LABEL SECS 'command to run on a node'
#   verify_checksums manifest.sha256 [dir]
#   record_access "dataset name"        (controlled-access data)
#   log_setup "what you did"            skip_if_done NAME / mark_done NAME
stage "Cluster: check the account"
if ! skip_if_done "cluster-account"; then
  say "Find your SLURM account and default partition."
  step "Run: sacctmgr show assoc user=\$USER format=account,partition"
  ask CLUSTER_ACCOUNT "Account name (the first column):"
  log_setup "SLURM account is $CLUSTER_ACCOUNT"
  mark_done "cluster-account"
fi
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
